def trace(input_data):
    sess = TraceSession(
        algorithm="Merge Intervals",
        input_data=input_data,
        pseudocode=["Sort intervals by start", "Maintain last merged interval, extend if overlaps"],
    )
    raw_iv = sess.intervals("input_intervals", input_data["intervals"])
    raw_iv.sort()
    intervals = sorted(input_data["intervals"])
    with sess.step("Sorted intervals"):
        pass
    merged_iv = sess.intervals("merged", [])
    for i, (s, e) in enumerate(intervals):
        with sess.step(f"Process [{s},{e}]"):
            raw_iv.highlight(i, role="current")
            if not merged_iv.to_list() or merged_iv.to_list()[-1][1] < s:
                merged_iv.append([s, e], reason=f"Non-overlapping, add [{s},{e}]")
            else:
                last = merged_iv.to_list()[-1]
                new_end = max(last[1], e)
                merged_iv.set(len(merged_iv.to_list())-1, [last[0], new_end], reason=f"Overlap, extend to {new_end}")
    with sess.step("Merge completed"):
        pass
    answer = merged_iv.to_list()
    sess.result(answer)
    trace = sess.to_trace()
    for ev in trace["events"]:
        op = ev.get("op")
        targets = [t["id"] for t in ev.get("targets", [])] if "targets" in ev else []
        if op == "sort" and "input_intervals" in targets:
            ev["code_line"] = 3
        elif op == "enter" and "Process" in ev.get("reason", ""):
            ev["code_line"] = 5
        elif op == "exit":
            ev["code_line"] = 5
        elif op == "set" and "merged" in targets:
            reason = ev.get("reason", "")
            if "add" in reason:
                ev["code_line"] = 7
            elif "extend" in reason:
                ev["code_line"] = 9
            else:
                ev["code_line"] = 5
        elif op == "highlight" and "input_intervals" in targets:
            ev["code_line"] = 5
        elif ev.get("role") == "answer":
            ev["code_line"] = 10
        else:
            ev["code_line"] = 5
    return trace

